/* ===========================================================================
 * test_cipher.c - tests for the block pipeline itself: Phase 2 encryption,
 * Phase 5 decryption, and the guarantee that a ciphertext this library
 * produces can be decrypted again.
 *
 * The known-answer vectors in vectors.h are generated by tools/gen_vectors.py,
 * a second implementation of docs/mountain_cipher_algorithm.md written from
 * the specification rather than from the C. Vectors recorded from the code
 * under test would agree with it by construction and would assert nothing;
 * these can disagree, which is the point.
 * ===========================================================================
 */

#include "test_framework.h"
#include "mountain_cipher.h"
#include "vectors.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* ---------------------------------------------------------------------
 * Known-answer tests
 * --------------------------------------------------------------------- */

static void test_known_answer_vectors(void) {
    fprintf(stderr, "test_known_answer_vectors:\n");

    for (size_t v = 0; v < MC_VECTOR_COUNT; v++) {
        const mc_vector_t *vec = &mc_vectors[v];
        size_t block_bytes = (size_t)vec->n * (size_t)vec->n;
        char msg[128];

        /* Step 1.3 - the key matrix must match byte for byte, including
         * how many XOF retries it took to find an invertible one. */
        mc_matrix_t key;
        mc_status_t st = mc_generate_key_matrix(vec->n, vec->seed, &key);
        snprintf(msg, sizeof(msg), "[%s] key generation succeeds", vec->label);
        MC_CHECK(st == MC_OK, msg);
        if (st != MC_OK) continue;

        snprintf(msg, sizeof(msg), "[%s] key matrix matches the specification", vec->label);
        MC_CHECK(memcmp(key.data, vec->key, sizeof(int64_t) * block_bytes) == 0, msg);

        /* Step 1.4 - padding */
        size_t padded_len = 0;
        uint8_t *padded = mc_pkcs7_pad(vec->plaintext, vec->plaintext_len,
                                        block_bytes, &padded_len);
        snprintf(msg, sizeof(msg), "[%s] padding succeeds", vec->label);
        MC_CHECK(padded != NULL, msg);
        if (!padded) { mc_matrix_free(&key); continue; }

        snprintf(msg, sizeof(msg), "[%s] padding produces %d block(s)",
                  vec->label, (int)vec->num_blocks);
        MC_CHECK(padded_len / block_bytes == vec->num_blocks, msg);

        /* Phase 2 - the ciphertext entries themselves */
        int64_t *ct = (int64_t *)malloc(sizeof(int64_t) * padded_len);
        st = mc_encrypt_blocks(&key, padded, padded_len, ct);
        snprintf(msg, sizeof(msg), "[%s] encryption succeeds", vec->label);
        MC_CHECK(st == MC_OK, msg);

        snprintf(msg, sizeof(msg), "[%s] ciphertext matches the specification (%s)",
                  vec->label, vec->branches);
        MC_CHECK(st == MC_OK &&
                  memcmp(ct, vec->ciphertext,
                         sizeof(int64_t) * vec->num_blocks * block_bytes) == 0, msg);

        /* Phase 5 - and back again */
        uint8_t *out = (uint8_t *)malloc(padded_len);
        mc_status_t dst = mc_decrypt_blocks(&key, ct, vec->num_blocks, out);
        snprintf(msg, sizeof(msg), "[%s] decryption returns the padded plaintext", vec->label);
        MC_CHECK(dst == MC_OK && memcmp(out, padded, padded_len) == 0, msg);

        long unpadded = mc_pkcs7_unpad_len(out, padded_len, block_bytes);
        snprintf(msg, sizeof(msg), "[%s] unpadding recovers the original length", vec->label);
        MC_CHECK(unpadded == (long)vec->plaintext_len, msg);

        snprintf(msg, sizeof(msg), "[%s] round trip reproduces the plaintext", vec->label);
        MC_CHECK(unpadded == (long)vec->plaintext_len &&
                  (vec->plaintext_len == 0 ||
                   memcmp(out, vec->plaintext, vec->plaintext_len) == 0), msg);

        free(out); free(ct); free(padded);
        mc_matrix_free(&key);
    }
}

/* ---------------------------------------------------------------------
 * The recoverability guarantee
 *
 * This is the regression test for the worst bug this project had: the
 * encryptor happily produced containers that the decryptor could never
 * open, and said "Encrypted" when it did. It is not hypothetical - at
 * n=8 it happened for roughly a quarter of keys and at n=9 for all of
 * them, because encryption multiplies small key entries while decryption
 * multiplies by the adjugate, whose entries grow factorially with n.
 * --------------------------------------------------------------------- */

static void test_encryption_is_never_silently_unrecoverable(void) {
    fprintf(stderr, "test_encryption_is_never_silently_unrecoverable:\n");

    const uint8_t sample[] = "the quick brown fox jumps over the lazy dog, twice over";
    int asymmetric_cases = 0;
    int checked = 0;

    for (int n = 2; n <= MC_MAX_N; n++) {
        for (int trial = 0; trial < 6; trial++) {
            uint8_t seed[MC_SEED_SIZE];
            for (int i = 0; i < MC_SEED_SIZE; i++) {
                seed[i] = (uint8_t)(i * 31 + n * 17 + trial * 101);
            }
            mc_matrix_t key;
            if (mc_generate_key_matrix(n, seed, &key) != MC_OK) continue;

            size_t block_bytes = (size_t)n * (size_t)n;
            size_t padded_len = 0;
            uint8_t *padded = mc_pkcs7_pad(sample, sizeof(sample) - 1,
                                            block_bytes, &padded_len);
            if (!padded) { mc_matrix_free(&key); continue; }

            int64_t *ct = (int64_t *)malloc(sizeof(int64_t) * padded_len);
            mc_status_t enc = mc_encrypt_blocks(&key, padded, padded_len, ct);

            if (enc == MC_OK) {
                mc_status_t rec = mc_encrypt_is_recoverable(&key, padded, padded_len, ct);
                if (rec != MC_OK) {
                    /* Encryption succeeded but the result cannot be read
                     * back. This is exactly the case the encryptor used
                     * to write to disk and call success. */
                    asymmetric_cases++;
                } else {
                    /* If the check passes it must be telling the truth:
                     * a full decryption has to reproduce the input. */
                    uint8_t *out = (uint8_t *)malloc(padded_len);
                    mc_status_t dec = mc_decrypt_blocks(&key, ct, padded_len / block_bytes, out);
                    char msg[96];
                    snprintf(msg, sizeof(msg),
                              "n=%d trial=%d: a ciphertext reported recoverable does decrypt",
                              n, trial);
                    MC_CHECK(dec == MC_OK && memcmp(out, padded, padded_len) == 0, msg);
                    free(out);
                    checked++;
                }
            }
            free(ct); free(padded);
            mc_matrix_free(&key);
        }
    }

    MC_CHECK(checked > 0, "the sweep actually encrypted something");

    /* If this ever stops being true the check has become dead weight and
     * somebody will delete it - so assert that it still has work to do,
     * and say why in the failure. */
    MC_CHECK(asymmetric_cases > 0,
              "the sweep still finds keys where encryption succeeds but decryption cannot");
}

/* ---------------------------------------------------------------------
 * Properties the two phases rely on
 * --------------------------------------------------------------------- */

static void test_work_key_preserves_determinant(void) {
    fprintf(stderr, "test_work_key_preserves_determinant:\n");

    /* Step 2.2 and 5.2 must agree, and both branches must leave the
     * determinant alone - that is what makes every block invertible. */
    uint8_t seed[MC_SEED_SIZE];
    for (int i = 0; i < MC_SEED_SIZE; i++) seed[i] = (uint8_t)(i * 7 + 11);

    for (int n = 2; n <= 6; n++) {
        mc_matrix_t key;
        if (mc_generate_key_matrix(n, seed, &key) != MC_OK) continue;
        int64_t det_key = 0;
        mc_determinant(&key, &det_key);

        /* Cover both branches and every row index, including negative
         * control determinants, which C's truncating % would otherwise
         * turn into a negative row index. */
        const int64_t ds[] = {0, 1, 2, 3, 7, 12, -1, -2, -7, -12};
        for (size_t k = 0; k < sizeof(ds) / sizeof(ds[0]); k++) {
            mc_matrix_t work;
            mc_status_t st = mc_block_work_key(&key, ds[k], &work);
            char msg[96];
            snprintf(msg, sizeof(msg), "n=%d d=%lld: work key derivation succeeds",
                      n, (long long)ds[k]);
            MC_CHECK(st == MC_OK, msg);
            if (st != MC_OK) continue;

            int64_t det_work = 0;
            mc_determinant(&work, &det_work);
            snprintf(msg, sizeof(msg), "n=%d d=%lld: work key has the key's determinant",
                      n, (long long)ds[k]);
            MC_CHECK(det_work == det_key, msg);

            /* The original key must be untouched - the spec's one rule. */
            int64_t det_key_again = 0;
            mc_determinant(&key, &det_key_again);
            snprintf(msg, sizeof(msg), "n=%d d=%lld: the original key is not mutated",
                      n, (long long)ds[k]);
            MC_CHECK(det_key_again == det_key, msg);
            mc_matrix_free(&work);
        }
        mc_matrix_free(&key);
    }
}

static void test_column_shift_commutes_with_multiplication(void) {
    fprintf(stderr, "test_column_shift_commutes_with_multiplication:\n");

    /* Decryption undoes the column shift on C, not on P - it shifts the
     * ciphertext back before multiplying by the adjugate. That is only
     * correct because a column shift is right-multiplication by a
     * permutation matrix and therefore commutes with the key's
     * left-multiplication. If it did not, every multi-column file would
     * come back scrambled. */
    mc_matrix_t k, p;
    mc_matrix_alloc(&k, 3);
    mc_matrix_alloc(&p, 3);
    int64_t kv[] = {2, -3, 5, 1, 4, -6, -7, 8, 9};
    int64_t pv[] = {10, 20, 30, 40, 50, 60, 70, 80, 90};
    memcpy(k.data, kv, sizeof(kv));
    memcpy(p.data, pv, sizeof(pv));

    for (int s = 0; s < 3; s++) {
        /* shift(P) then multiply */
        mc_matrix_t p_shifted, left;
        mc_matrix_copy(&p, &p_shifted);
        mc_cyclic_column_shift(&p_shifted, s);
        mc_matrix_multiply(&k, &p_shifted, &left);

        /* multiply then shift the product */
        mc_matrix_t right;
        mc_matrix_multiply(&k, &p, &right);
        mc_cyclic_column_shift(&right, s);

        char msg[80];
        snprintf(msg, sizeof(msg), "shift %d commutes with left multiplication", s);
        MC_CHECK(memcmp(left.data, right.data, sizeof(int64_t) * 9) == 0, msg);

        mc_matrix_free(&p_shifted); mc_matrix_free(&left); mc_matrix_free(&right);
    }
    mc_matrix_free(&k); mc_matrix_free(&p);
}

/* Encrypts `data` with the given key, returning a malloc'd block array. */
static int64_t *encrypt_copy(const mc_matrix_t *key, const uint8_t *data,
                              size_t len, size_t *padded_len_out) {
    size_t block_bytes = (size_t)key->n * (size_t)key->n;
    size_t padded_len = 0;
    uint8_t *padded = mc_pkcs7_pad(data, len, block_bytes, &padded_len);
    if (!padded) return NULL;
    int64_t *ct = (int64_t *)malloc(sizeof(int64_t) * padded_len);
    if (!ct) { free(padded); return NULL; }
    if (mc_encrypt_blocks(key, padded, padded_len, ct) != MC_OK) {
        free(padded); free(ct); return NULL;
    }
    free(padded);
    if (padded_len_out) *padded_len_out = padded_len;
    return ct;
}

static void test_block_chaining_propagates_a_changed_determinant(void) {
    fprintf(stderr, "test_block_chaining_propagates_a_changed_determinant:\n");

    /* Each block's mutation and shift are chosen by det(C_{i-1}), so a
     * change to block 0 that changes that determinant's parity or its
     * value mod n must change every block after it. */
    uint8_t seed[MC_SEED_SIZE];
    for (int i = 0; i < MC_SEED_SIZE; i++) seed[i] = (uint8_t)(i * 19 + 7);
    mc_matrix_t key;
    MC_CHECK(mc_generate_key_matrix(3, seed, &key) == MC_OK, "key generation succeeds");
    size_t block_bytes = 9;

    /* Bytes chosen so that no block matrix is singular, which is the case
     * where chaining carries information at all - see the test below. */
    uint8_t base[27] = {
        0x5b, 0x11, 0xa3, 0x07, 0xe2, 0x49, 0x8c, 0x30, 0xd1,
        0x62, 0xbb, 0x1f, 0x94, 0x2d, 0x7a, 0xc6, 0x08, 0x53,
        0xfd, 0x41, 0x96, 0x2b, 0xcf, 0x74, 0x1a, 0xe9, 0x35
    };

    size_t padded_len = 0;
    int64_t *ct_base = encrypt_copy(&key, base, sizeof(base), &padded_len);
    MC_CHECK(ct_base != NULL, "the baseline encrypts");
    size_t blocks = padded_len / block_bytes;
    MC_CHECK(blocks >= 3, "the fixture spans at least three blocks");

    /* Try a flip in several positions of block 0; count the ones that
     * actually move the chaining value, and require that whenever it
     * moves, every later block moves with it. */
    int propagating_flips = 0;
    for (size_t pos = 0; pos < block_bytes && ct_base; pos++) {
        uint8_t variant[27];
        memcpy(variant, base, sizeof(base));
        variant[pos] ^= 0x01;

        int64_t *ct_var = encrypt_copy(&key, variant, sizeof(variant), NULL);
        if (!ct_var) continue;

        /* Did the control determinant handed to block 1 actually change
         * in the only two ways block 1 can observe? */
        mc_matrix_t c0_base, c0_var;
        mc_matrix_alloc(&c0_base, 3);
        mc_matrix_alloc(&c0_var, 3);
        memcpy(c0_base.data, ct_base, sizeof(int64_t) * block_bytes);
        memcpy(c0_var.data, ct_var, sizeof(int64_t) * block_bytes);
        int64_t d_base = 0, d_var = 0;
        mc_determinant(&c0_base, &d_base);
        mc_determinant(&c0_var, &d_var);
        mc_matrix_free(&c0_base);
        mc_matrix_free(&c0_var);

        int observable = (((d_base % 2) + 2) % 2) != (((d_var % 2) + 2) % 2) ||
                          (((d_base % 3) + 3) % 3) != (((d_var % 3) + 3) % 3);
        if (observable) {
            propagating_flips++;
            /* The block immediately after the change must differ: that is
             * the whole of what the chaining mechanism does. */
            MC_CHECK(memcmp(ct_base + 1 * block_bytes, ct_var + 1 * block_bytes,
                             sizeof(int64_t) * block_bytes) != 0,
                      "a changed control determinant changes the next block");
        }
        free(ct_var);
    }
    MC_CHECK(propagating_flips > 0,
              "at least one single-bit change to block 0 reaches the next block");

    free(ct_base);
    mc_matrix_free(&key);
}

static void test_chaining_does_not_reach_past_the_next_block(void) {
    fprintf(stderr, "test_chaining_does_not_reach_past_the_next_block:\n");

    /* Another pinned WEAKNESS - see README "Known Limitations".
     *
     * The chaining looks cumulative but is not. Block i's control
     * determinant is det(C_{i-1}), and C_{i-1} = work_key x P_{i-1}, so
     *
     *     det(C_{i-1}) = +/- det(work_key) x det(P_{i-1})
     *                  = +/- det(key)      x det(P_{i-1})
     *
     * because every Step 2.2 branch preserves det(key) - the property the
     * design is built on. That determinant therefore depends on the
     * previous PLAINTEXT block alone, and not on anything before it. The
     * only way an earlier change can reach further than one block is by
     * flipping the sign of a later determinant.
     *
     * So a one-bit change early in a file does not avalanche: here it
     * changes the next block and then stops, leaving the rest of the
     * ciphertext byte-identical. */
    uint8_t seed[MC_SEED_SIZE];
    for (int i = 0; i < MC_SEED_SIZE; i++) seed[i] = (uint8_t)(i * 19 + 7);
    mc_matrix_t key;
    mc_generate_key_matrix(3, seed, &key);

    uint8_t base[27] = {
        0x5b, 0x11, 0xa3, 0x07, 0xe2, 0x49, 0x8c, 0x30, 0xd1,
        0x62, 0xbb, 0x1f, 0x94, 0x2d, 0x7a, 0xc6, 0x08, 0x53,
        0xfd, 0x41, 0x96, 0x2b, 0xcf, 0x74, 0x1a, 0xe9, 0x35
    };
    uint8_t variant[27];
    memcpy(variant, base, sizeof(base));
    variant[0] ^= 0x01;

    size_t padded_len = 0;
    int64_t *ct_base = encrypt_copy(&key, base, sizeof(base), &padded_len);
    int64_t *ct_var = encrypt_copy(&key, variant, sizeof(variant), NULL);
    MC_CHECK(ct_base != NULL && ct_var != NULL, "both variants encrypt");

    if (ct_base && ct_var) {
        size_t blocks = padded_len / 9;
        MC_CHECK(blocks >= 4, "the fixture spans at least four blocks");
        MC_CHECK(memcmp(ct_base + 9, ct_var + 9, sizeof(int64_t) * 9) != 0,
                  "the block after the change does differ");

        int tail_identical = 1;
        for (size_t blk = 2; blk < blocks; blk++) {
            if (memcmp(ct_base + blk * 9, ct_var + blk * 9, sizeof(int64_t) * 9) != 0) {
                tail_identical = 0;
            }
        }
        MC_CHECK(tail_identical,
                  "the change does NOT reach blocks 2 onward "
                  "(documented weakness - see README 'Known Limitations')");

        /* The mechanism: the determinant handed to block 2 is the same in
         * both runs, because it is a function of P_1, not of C_1's
         * contents. */
        mc_matrix_t a, b;
        mc_matrix_alloc(&a, 3);
        mc_matrix_alloc(&b, 3);
        memcpy(a.data, ct_base + 9, sizeof(int64_t) * 9);
        memcpy(b.data, ct_var + 9, sizeof(int64_t) * 9);
        int64_t da = 0, db = 0;
        mc_determinant(&a, &da);
        mc_determinant(&b, &db);
        MC_CHECK(da == db,
                  "the next block's own determinant is unchanged, so the chain stops");
        mc_matrix_free(&a); mc_matrix_free(&b);
    }
    free(ct_base); free(ct_var);
    mc_matrix_free(&key);
}

static void test_identical_blocks_produce_identical_ciphertext(void) {
    fprintf(stderr, "test_identical_blocks_produce_identical_ciphertext:\n");

    /* This pins a WEAKNESS, not a feature, and it is here so that nobody
     * reads the specification's "block chaining" row and believes more
     * than it says. See README "Known Limitations".
     *
     * C = work_key x P, so det(C) = +/- det(key) x det(P), and det(P) is
     * zero for any block whose byte matrix is singular - a run of one
     * repeated byte, for instance. The chaining value handed to the next
     * block is then zero whatever came before it, so every such block is
     * encrypted with the same mutation (row 0) and the same shift (none).
     * Identical plaintext blocks therefore come out as identical
     * ciphertext blocks, which is the property ECB mode is notorious for.
     *
     * If this test ever fails, the cipher has changed in a way that fixes
     * the flaw. That is good news, but the README must change with it. */
    uint8_t seed[MC_SEED_SIZE];
    for (int i = 0; i < MC_SEED_SIZE; i++) seed[i] = (uint8_t)(i * 3 + 1);
    mc_matrix_t key;
    mc_generate_key_matrix(4, seed, &key);

    uint8_t repeated[16 * 5];
    memset(repeated, 'A', sizeof(repeated));
    size_t padded_len = 0;
    int64_t *ct = encrypt_copy(&key, repeated, sizeof(repeated), &padded_len);
    MC_CHECK(ct != NULL, "the repeating fixture encrypts");

    if (ct) {
        /* Blocks 1..4 are the repeated ones. Block 0 uses det(key) as its
         * control determinant rather than a previous block, and the last
         * block is padding. */
        int repeats_leak = 1;
        for (size_t blk = 2; blk <= 4; blk++) {
            if (memcmp(ct + 1 * 16, ct + blk * 16, sizeof(int64_t) * 16) != 0) {
                repeats_leak = 0;
            }
        }
        MC_CHECK(repeats_leak,
                  "identical plaintext blocks still produce identical ciphertext "
                  "(documented weakness - see README 'Known Limitations')");

        /* The mechanism behind it: the control determinant is zero. */
        mc_matrix_t c1;
        mc_matrix_alloc(&c1, 4);
        memcpy(c1.data, ct + 1 * 16, sizeof(int64_t) * 16);
        int64_t d = 12345;
        mc_determinant(&c1, &d);
        MC_CHECK(d == 0, "a singular plaintext block gives a zero control determinant");
        mc_matrix_free(&c1);
        free(ct);
    }
    mc_matrix_free(&key);
}

static void test_decrypt_rejects_a_wrong_key(void) {
    fprintf(stderr, "test_decrypt_rejects_a_wrong_key:\n");

    /* Decrypting with the wrong key must not reproduce the plaintext.
     * It is allowed to fail, and it is allowed to return bytes - what it
     * must never do is return the right bytes. */
    uint8_t seed_a[MC_SEED_SIZE], seed_b[MC_SEED_SIZE];
    for (int i = 0; i < MC_SEED_SIZE; i++) {
        seed_a[i] = (uint8_t)(i * 9 + 1);
        seed_b[i] = (uint8_t)(i * 9 + 2);
    }
    mc_matrix_t key_a, key_b;
    mc_generate_key_matrix(4, seed_a, &key_a);
    mc_generate_key_matrix(4, seed_b, &key_b);

    const uint8_t plain[] = "attack at dawn, bring the good biscuits";
    size_t padded_len = 0;
    uint8_t *padded = mc_pkcs7_pad(plain, sizeof(plain) - 1, 16, &padded_len);
    int64_t *ct = (int64_t *)malloc(sizeof(int64_t) * padded_len);
    MC_CHECK(mc_encrypt_blocks(&key_a, padded, padded_len, ct) == MC_OK, "encrypt with key A");

    uint8_t *out = (uint8_t *)malloc(padded_len);
    memset(out, 0, padded_len);
    mc_status_t st = mc_decrypt_blocks(&key_b, ct, padded_len / 16, out);
    MC_CHECK(st != MC_OK || memcmp(out, padded, padded_len) != 0,
              "decrypting with key B does not reproduce the plaintext");

    /* And the padding check that the CLI relies on must reject it. */
    if (st == MC_OK) {
        long unpadded = mc_pkcs7_unpad_len(out, padded_len, 16);
        MC_CHECK(unpadded < 0 || (size_t)unpadded != sizeof(plain) - 1 ||
                  memcmp(out, plain, sizeof(plain) - 1) != 0,
                  "wrong-key output does not survive the padding check as the original");
    }

    free(out); free(ct); free(padded);
    mc_matrix_free(&key_a); mc_matrix_free(&key_b);
}

static void test_block_api_rejects_bad_arguments(void) {
    fprintf(stderr, "test_block_api_rejects_bad_arguments:\n");

    uint8_t seed[MC_SEED_SIZE];
    memset(seed, 0x5A, sizeof(seed));
    mc_matrix_t key;
    mc_generate_key_matrix(3, seed, &key);

    uint8_t padded[27] = {0};
    int64_t ct[27] = {0};

    MC_CHECK(mc_encrypt_blocks(NULL, padded, 27, ct) != MC_OK, "encrypt rejects a null key");
    MC_CHECK(mc_encrypt_blocks(&key, NULL, 27, ct) != MC_OK, "encrypt rejects null input");
    MC_CHECK(mc_encrypt_blocks(&key, padded, 27, NULL) != MC_OK, "encrypt rejects a null output");
    MC_CHECK(mc_encrypt_blocks(&key, padded, 10, ct) == MC_ERR_BAD_FORMAT,
              "encrypt rejects a length that is not a whole number of blocks");
    MC_CHECK(mc_decrypt_blocks(NULL, ct, 3, padded) != MC_OK, "decrypt rejects a null key");
    MC_CHECK(mc_block_work_key(NULL, 0, &key) != MC_OK, "work key derivation rejects a null key");

    mc_matrix_free(&key);
}

int main(void) {
    test_known_answer_vectors();
    test_encryption_is_never_silently_unrecoverable();
    test_work_key_preserves_determinant();
    test_column_shift_commutes_with_multiplication();
    test_block_chaining_propagates_a_changed_determinant();
    test_chaining_does_not_reach_past_the_next_block();
    test_identical_blocks_produce_identical_ciphertext();
    test_decrypt_rejects_a_wrong_key();
    test_block_api_rejects_bad_arguments();
    MC_TEST_EXIT();
}
